<?php
require_once __DIR__.'/../includes/init.php';require_role('petugas');require_once __DIR__.'/../includes/layout.php';$pdo=db();$q=trim((string)($_GET['q']??''));$p=[];$w="t.status='masuk'";if($q!==''){$w.=' AND (k.plat_nomor LIKE ? OR k.pemilik LIKE ? OR CAST(t.id_parkir AS CHAR) LIKE ?)';array_push($p,'%'.$q.'%','%'.$q.'%','%'.$q.'%');}$s=$pdo->prepare("SELECT t.id_parkir,t.waktu_masuk,t.tarif_saat_masuk,k.plat_nomor,k.jenis_kendaraan,k.pemilik,a.nama_area,TIMESTAMPDIFF(SECOND,t.waktu_masuk,NOW()) AS elapsed FROM tb_transaksi t JOIN tb_kendaraan k ON k.id_kendaraan=t.id_kendaraan JOIN tb_area_parkir a ON a.id_area=t.id_area WHERE $w ORDER BY t.waktu_masuk ASC");$s->execute($p);$rows=$s->fetchAll();render_header('Kendaraan Sedang Parkir','aktif');?>
<div class="page-intro"><div><h2>Kendaraan sedang parkir</h2><p>Daftar transaksi aktif yang belum memiliki waktu keluar.</p></div><a class="btn btn-primary" href="<?= h(url('petugas/transaksi-keluar.php')) ?>">↑ Proses kendaraan keluar</a></div><section class="panel"><div class="table-toolbar"><div><strong><?= count($rows) ?> kendaraan aktif</strong><div class="muted" style="margin-top:4px">Durasi estimasi dibulatkan ke atas saat proses keluar.</div></div><form method="get" class="toolbar-right"><div class="search-box"><input name="q" value="<?= h($q) ?>" placeholder="Plat, pemilik, ID transaksi"></div><button class="btn btn-secondary">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Kendaraan</th><th>Area</th><th>Waktu masuk</th><th>Durasi sementara</th><th>Tarif snapshot</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):$hrs=max(1,(int)ceil((int)$r['elapsed']/3600));?><tr><td class="td-main">#<?= (int)$r['id_parkir'] ?></td><td class="td-main"><?= h($r['plat_nomor']) ?><div class="muted"><?= h(ucfirst($r['jenis_kendaraan']).' · '.$r['pemilik']) ?></div></td><td><?= h($r['nama_area']) ?></td><td><?= h(tanggal($r['waktu_masuk'])) ?></td><td><?= $hrs ?> jam (sementara)</td><td><?= h(rupiah($r['tarif_saat_masuk'])) ?>/jam</td><td><a class="btn btn-primary btn-sm" href="<?= h(url('petugas/transaksi-keluar.php?id='.(int)$r['id_parkir'])) ?>">Proses keluar</a></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="7"><div class="empty-state"><div class="empty-icon">✓</div><strong>Tidak ada kendaraan aktif</strong>Semua transaksi parkir sudah selesai.</div></td></tr><?php endif; ?></tbody></table></div></section><?php render_footer(); ?>